/// True when `cp` has the Cased property.
pub fn isCased(cp: u21) bool {
    return inRanges(&cased_ranges, cp);
}

/// True when `cp` has the Case_Ignorable property.
pub fn isCaseIgnorable(cp: u21) bool {
    return inRanges(&ignorable_ranges, cp);
}

/// True when `cp` may start an identifier (XID_Start, UAX #31).
/// ASCII `"_"` is allowed separately by the lexer.
pub fn isXidStart(cp: u21) bool {
    return inRanges(&xid_start_ranges, cp);
}

/// True when `cp` may continue an identifier (XID_Continue, UAX #31).
/// ASCII `"_"` is allowed separately by the lexer.
pub fn isXidContinue(cp: u21) bool {
    return inRanges(&xid_continue_ranges, cp);
}

fn inRanges(ranges: []const [2]u32, cp: u21) bool {
    const c: u32 = cp;
    for (ranges) |r| {
        if (c < r[0]) return false;
        if (c <= r[1]) return true;
    }
    return false;
}

fn search(comptime T: type, table: []const T, cp: u32) ?T {
    var lo: usize = 0;
    var hi: usize = table.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        if (table[mid].cp < cp) lo = mid + 1 else hi = mid;
    }
    if (lo >= table.len or table[lo].cp != cp) return null;
    return table[lo];
}

/// The simple mapping of `cp`, or null when it maps to itself.
pub fn lookupSimple(cp: u21) ?Simple {
    return search(Simple, &simple, cp);
}

/// The unconditional full lowercase expansion of `cp`, or null.
pub fn lookupSpecialLower(cp: u21) ?Special {
    return search(Special, &special_lower, cp);
}

/// The unconditional full uppercase expansion of `cp`, or null.
pub fn lookupSpecialUpper(cp: u21) ?Special {
    return search(Special, &special_upper, cp);
}

test "tables are sorted by cp / lo" {
    for (simple[1..], 0..) |m, i| try std.testing.expect(simple[i].cp < m.cp);
    for (special_lower[1..], 0..) |m, i| try std.testing.expect(special_lower[i].cp < m.cp);
    for (special_upper[1..], 0..) |m, i| try std.testing.expect(special_upper[i].cp < m.cp);
    for (cased_ranges[1..], 0..) |r, i| try std.testing.expect(cased_ranges[i][1] < r[0]);
    for (ignorable_ranges[1..], 0..) |r, i| try std.testing.expect(ignorable_ranges[i][1] < r[0]);
    for (xid_start_ranges[1..], 0..) |r, i| try std.testing.expect(xid_start_ranges[i][1] < r[0]);
    for (xid_continue_ranges[1..], 0..) |r, i| try std.testing.expect(xid_continue_ranges[i][1] < r[0]);
}

test "Final_Sigma context spot checks" {
    // Combining acute is Case_Ignorable, µ is Other_Lowercase Cased,
    // apostrophe and middle dot are Case_Ignorable, Σ is Cased.
    try std.testing.expect(isCaseIgnorable(0x301));
    try std.testing.expect(!isCased(0x301));
    try std.testing.expect(isCased(0x3A3));
    try std.testing.expect(isCased(0xB5));
    try std.testing.expect(isCaseIgnorable(0x27));
    try std.testing.expect(isCaseIgnorable(0xB7));
    // XID spot checks: Greek letters are identifier characters,
    // combining marks continue but do not start, emoji do neither.
    try std.testing.expect(isXidStart(0x3BA)); // κ
    try std.testing.expect(isXidContinue(0x3BA));
    try std.testing.expect(!isXidStart(0x301)); // combining acute
    try std.testing.expect(isXidContinue(0x301));
    try std.testing.expect(!isXidStart(0x1F600)); // emoji
    try std.testing.expect(!isXidContinue(0x1F600));
    try std.testing.expect(isXidContinue('0')); // digits continue
    try std.testing.expect(!isXidStart('0'));
}

const std = @import("std");
